/** Compat: la forma que consumen runner y orquestador. El systemPrompt se
 *  genera del contrato, no se escribe a mano. */
export const AGENTS: Record<AgentKey, AgentSpec & { systemPrompt: string }> =
  Object.fromEntries(
    (Object.keys(AGENT_SPECS) as AgentKey[]).map((k) => [
      k,
      { ...AGENT_SPECS[k], systemPrompt: buildSystemPrompt(AGENT_SPECS[k]) },
    ])
  ) as Record<AgentKey, AgentSpec & { systemPrompt: string }>;
